// Sanitiza logs: não registrar URLs com tokens, credenciais ou payloads.
const raw=$input.first().json||{};
const execution=raw.execution||{};
const workflow=raw.workflow||{};
const error=execution.error||raw.error||{};
const secretPattern=/([?&](?:token|key|api_key|app_key|app_id|access_token|password|secret)=)[^&\s]+/gi;
const redact=value=>String(value??'').replace(secretPattern,'$1[REDACTED]')
  .replace(/(Authorization\s*:\s*)(?:Bearer|Basic)\s+[^\s]+/gi,'$1[REDACTED]')
  .replace(/(\/api\/)[A-Za-z0-9_-]{18,}/g,'$1[REDACTED]')
  .replace(/(postgres(?:ql)?:\/\/)[^@\s]+@/gi,'$1[REDACTED]@')
  .slice(0,600);
const runKey=String(execution.id||raw.executionId||new Date().toISOString());
return [{json:{runKey,workflow:workflow.name||'Não informado',
 kind:'error',stage:redact(execution.lastNodeExecuted||'unknown'),
 message:redact(error.message||'Falha não especificada'),at:new Date().toISOString()}}];
